-- Topics become rows an operator edits as a tree, instead of a JSON document typed into
-- the panel. The AI reads the active rows at analysis time; intents, journey stages and
-- severity rules are system vocabulary and no longer part of what an operator maintains.

CREATE TABLE IF NOT EXISTS topic (
    id          UUID PRIMARY KEY,
    tenant_id   VARCHAR(64)  NOT NULL,
    taxonomy_id UUID         NOT NULL REFERENCES taxonomy(id) ON DELETE CASCADE,
    parent_id   UUID         REFERENCES topic(id) ON DELETE RESTRICT,
    -- Stable machine key stored on AI results; generated by the server, never typed.
    code        VARCHAR(128) NOT NULL,
    title       VARCHAR(200) NOT NULL,
    -- What belongs under this topic. It is the AI's main guidance for choosing it.
    description TEXT,
    keywords    TEXT[]       NOT NULL DEFAULT '{}',
    sort_order  INT          NOT NULL DEFAULT 0,
    is_active   BOOLEAN      NOT NULL DEFAULT true,
    created_by  VARCHAR(128),
    updated_by  VARCHAR(128),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_topic_code UNIQUE (taxonomy_id, code),
    CONSTRAINT ck_topic_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id)
);

CREATE INDEX IF NOT EXISTS ix_topic_parent ON topic (taxonomy_id, parent_id, sort_order);

-- AI judgements come from a dedicated decision model; the text model only writes.
ALTER TABLE ai_analysis
    ADD COLUMN IF NOT EXISTS decision_model VARCHAR(128);

-- Every edit bumps the revision; AI results record it as their taxonomy_version.
ALTER TABLE taxonomy
    ADD COLUMN IF NOT EXISTS revision INT NOT NULL DEFAULT 1;

-- Carry the active JSON definition over as the initial tree.
INSERT INTO topic (id, tenant_id, taxonomy_id, parent_id, code, title, sort_order, created_by, updated_by)
SELECT gen_random_uuid(), t.tenant_id, t.id, NULL,
       c.value->>'key',
       COALESCE(c.value->>'label_fa', c.value->>'key'),
       (c.ordinality - 1)::int * 10,
       'system', 'system'
FROM taxonomy t
JOIN taxonomy_version tv ON tv.id = t.active_version_id
CROSS JOIN LATERAL jsonb_array_elements(tv.definition->'categories') WITH ORDINALITY AS c(value, ordinality)
WHERE c.value->>'key' IS NOT NULL
ON CONFLICT (taxonomy_id, code) DO NOTHING;

-- Subcategory keys repeat across categories ("timeout"), so the child code is qualified.
INSERT INTO topic (id, tenant_id, taxonomy_id, parent_id, code, title, sort_order, created_by, updated_by)
SELECT gen_random_uuid(), parent.tenant_id, parent.taxonomy_id, parent.id,
       parent.code || '.' || (s.value #>> '{}'),
       COALESCE(labels.title, replace(s.value #>> '{}', '_', ' ')),
       (s.ordinality - 1)::int * 10,
       'system', 'system'
FROM taxonomy t
JOIN taxonomy_version tv ON tv.id = t.active_version_id
CROSS JOIN LATERAL jsonb_array_elements(tv.definition->'categories') AS c(value)
JOIN topic parent ON parent.taxonomy_id = t.id AND parent.parent_id IS NULL AND parent.code = c.value->>'key'
CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.value->'subcategories', '[]'::jsonb)) WITH ORDINALITY AS s(value, ordinality)
LEFT JOIN (VALUES
    ('credential_configuration', 'User name and password settings'),
    ('invalid_credentials', 'Incorrect password or username'),
    ('otp', 'One-time use code'),
    ('session_expiry', 'The end of the meeting'),
    ('invoice', 'Invoice'),
    ('refund', 'Refund'),
    ('pricing', 'Pricing'),
    ('payment_failure', 'Failure to pay'),
    ('timeout', 'Timeout'),
    ('gateway_error', 'Port error'),
    ('settlement', 'Settlement'),
    ('reversal', 'Transaction reversal'),
    ('api_error', 'Error API'),
    ('webhook', 'Webhook'),
    ('sdk', 'Development kit (SDK)'),
    ('documentation', 'Documentation'),
    ('latency', 'slowness'),
    ('availability', 'Unavailability'),
    ('registration', 'Registration'),
    ('kyc', 'Document authentication'),
    ('activation', 'Activation'),
    ('how_to', 'How to use'),
    ('feature_request', 'Capability Request'),
    ('ui_issue', 'Appearance problem'),
    ('response_time', 'Response time'),
    ('resolution_quality', 'The quality of problem solving'),
    ('agent_behavior', 'Expert behavior')
) AS labels(code, title) ON labels.code = s.value #>> '{}'
WHERE jsonb_typeof(s.value) = 'string'
ON CONFLICT (taxonomy_id, code) DO NOTHING;
